package com.gestordevendas.api.food; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; @RestController @RequestMapping("/api/food") public class FoodController {private final FoodService s; public FoodController(FoodService s){this.s=s;} @GetMapping("/couriers") public List<CourierResponse> couriers(){return s.couriers();} @PostMapping("/couriers") public CourierResponse createCourier(@Valid @RequestBody CourierRequest r){return s.saveCourier(null,r);} @PutMapping("/couriers/{id}") public CourierResponse updateCourier(@PathVariable UUID id, @Valid @RequestBody CourierRequest r){return s.saveCourier(id,r);} @DeleteMapping("/couriers/{id}") public void deleteCourier(@PathVariable UUID id){s.deleteCourier(id);} @GetMapping("/couriers/report") public CourierReportResponse report(){return s.report();} @GetMapping("/snacks") public List<SnackResponse> snacks(){return s.snacks();} @PostMapping("/snacks") public SnackResponse createSnack(@Valid @RequestBody SnackRequest r){return s.saveSnack(null,r);} @PutMapping("/snacks/{id}") public SnackResponse updateSnack(@PathVariable UUID id, @Valid @RequestBody SnackRequest r){return s.saveSnack(id,r);} @DeleteMapping("/snacks/{id}") public void deleteSnack(@PathVariable UUID id){s.deleteSnack(id);} @GetMapping("/beverages") public List<BeverageResponse> beverages(){return s.beverages();} @PostMapping("/beverages") public BeverageResponse createBeverage(@Valid @RequestBody BeverageRequest r){return s.saveBeverage(null,r);} @PutMapping("/beverages/{id}") public BeverageResponse updateBeverage(@PathVariable UUID id, @Valid @RequestBody BeverageRequest r){return s.saveBeverage(id,r);} @DeleteMapping("/beverages/{id}") public void deleteBeverage(@PathVariable UUID id){s.deleteBeverage(id);} @PutMapping("/orders/{id}/approval") public SnackOrderResponse approve(@PathVariable UUID id, @RequestParam boolean accept){return s.approvePublicOrder(id,accept);} @GetMapping("/orders") public List<SnackOrderResponse> orders(){return s.orders();} @PostMapping("/orders") public SnackOrderResponse order(@Valid @RequestBody SnackOrderRequest r){return s.createOrder(r);} @PutMapping("/orders/{id}/confirm") public SnackOrderResponse confirmOrder(@PathVariable UUID id, @RequestBody ConfirmSnackPaymentRequest r){return s.confirmOrder(id,r.paymentMethod(),r.cashReceived());} @PutMapping("/orders/{id}") public SnackOrderResponse editOrder(@PathVariable UUID id, @Valid @RequestBody SnackOrderRequest r){return s.editOrder(id,r);} @DeleteMapping("/orders/{id}") public void cancelOrder(@PathVariable UUID id, @RequestParam(defaultValue="false") boolean refund){s.cancelOrder(id,refund);} @GetMapping("/tables") public List<Integer> tables(){return s.tables();} @PostMapping("/tables") public List<Integer> addTable(){return s.addTable();} @GetMapping("/kitchen") public List<SnackOrderResponse> kitchen(){return s.kitchen();} @PutMapping("/kitchen/{id}") public SnackOrderResponse kitchenStatus(@PathVariable UUID id, @RequestParam String status){return s.kitchenStatus(id,status);} @GetMapping("/costs") public List<SnackCostResponse> costs(){return s.costs();} @PutMapping("/costs/{snackId}") public SnackCostResponse saveCost(@PathVariable UUID snackId, @Valid @RequestBody SnackCostRequest r){return s.saveCost(snackId,r);} @GetMapping("/stats") public SnackStatsResponse stats(@RequestParam Instant from, @RequestParam Instant to){return s.stats(from,to);} @GetMapping("/cash") public CashSummaryResponse cash(@RequestParam LocalDate date){return s.cash(date);} }
